const GroupService=(function(){const KEY="pp_group_id";const LEGACY_KEY="pp_players";const LEGACY_ID="LEGACY";const ALPHABET="0123456789ABCDEFGHJKMNPQRSTVWXYZ";function _random(len){const out=[];const g=typeof globalThis!=="undefined"?globalThis:{};const crypto=g.crypto||g.msCrypto;if(crypto&&crypto.getRandomValues){const buf=new Uint8Array(len);crypto.getRandomValues(buf);for(let i=0;i<len;i++)out.push(ALPHABET[buf[i]%ALPHABET.length])}else{for(let i=0;i<len;i++)out.push(ALPHABET[Math.floor(Math.random()*ALPHABET.length)])}return out.join("")}function newGroupId(){return _random(26)}function _store(){try{return typeof localStorage!=="undefined"?localStorage:null}catch(e){return null}}function normalizeCode(input){return String(input||"").toUpperCase().replace(/[^0-9A-Z]/g,"").replace(/[ILO]/g,c=>({I:"1",L:"1",O:"0"})[c]).replace(/U/g,"V")}function isValidCode(input){const c=normalizeCode(input);return c.length>=8&&c.length<=40&&!/[ILOU]/.test(c)}function current(){const store=_store();if(!store)return LEGACY_ID;let id=store.getItem(KEY);if(id)return id;id=store.getItem(LEGACY_KEY)?LEGACY_ID:newGroupId();store.setItem(KEY,id);return id}function isLegacy(){return current()===LEGACY_ID}function join(code){if(!isValidCode(code))return null;const id=normalizeCode(code);const store=_store();if(store)store.setItem(KEY,id);return id}function reset(){const id=newGroupId();const store=_store();if(store)store.setItem(KEY,id);return id}function displayCode(id){const c=id||current();return(c.match(/.{1,4}/g)||[c]).join("-")}return{LEGACY_ID,newGroupId,normalizeCode,isValidCode,current,isLegacy,join,reset,displayCode}})();if(typeof window!=="undefined"){Object.assign(window,{GroupService})}
